package com.keevo.identity.onboarding.adapter.out.persistence;

import jakarta.persistence.*;

import java.time.Instant;
import java.time.LocalTime;
import java.util.UUID;

/**
 * TenantPreferencesJpaEntity — JPA entity for the {@code tenant_preferences} table.
 *
 * <p>Table created by {@link com.keevo.shared.infrastructure.persistence.TenantSchemaProvisioner}
 * (DDL_TENANT_PREFERENCES constant) within each tenant's PostgreSQL schema.
 *
 * <p>UUID is generated by Hibernate — never passed from the caller.
 */
@Entity
@Table(name = "tenant_preferences")
public class TenantPreferencesJpaEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Column(name = "sector_type", length = 30)
    private String sectorType;

    @Column(name = "eod_report_time", nullable = false)
    private LocalTime eodReportTime;

    @Column(name = "stock_alert_enabled", nullable = false)
    private boolean stockAlertEnabled;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    // ── JPA requires no-arg constructor ───────────────────────────────────────
    protected TenantPreferencesJpaEntity() {}

    /** Factory constructor — id is intentionally omitted; Hibernate generates it. */
    public TenantPreferencesJpaEntity(String sectorType, LocalTime eodReportTime,
                                       boolean stockAlertEnabled, Instant createdAt,
                                       Instant updatedAt) {
        this.sectorType = sectorType;
        this.eodReportTime = eodReportTime;
        this.stockAlertEnabled = stockAlertEnabled;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    // ── Accessors ────────────────────────────────────────────────────────────

    public UUID getId() { return id; }
    public String getSectorType() { return sectorType; }
    public LocalTime getEodReportTime() { return eodReportTime; }
    public boolean isStockAlertEnabled() { return stockAlertEnabled; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
}
